/* output.c: the generated files (see output.h). */
#include "output.h"

#include <stdlib.h>
#include <string.h>

#include "funcgen.h"
#include "module.h"
#include "stream.h"

static const char *base_name(const char *prefix) {
    const char *slash = strrchr(prefix, '/');
    return slash ? slash + 1 : prefix;
}

static void banner(Buf *b, const char *what) {
    bprintf(b,
            "/* %s\n"
            " * Generated by sultanc-wasm2c from bootstrap-wasm/seed/sultanc.wasm.zst. Do not edit. */\n",
            what);
}

void write_header(const char *prefix) {
    Buf b = {0};
    uint32_t i;
    banner(&b, "The translated SultanC seed: declarations shared by its units.");
    buf_puts(&b, "#ifndef SULTANC_SEED_H\n#define SULTANC_SEED_H\n\n#include \"w2c.h\"\n\n");
    if (num_globals) {
        buf_puts(&b, "/* Globals. */\n");
        for (i = 0; i < num_globals; i++) bprintf(&b, "extern %s w2c_g%" PRIu32 ";\n", ctype(globals[i].type), i);
        buf_puts(&b, "\n");
    }
    buf_puts(&b, "/* WASI host functions (runtime/wasi.c). */\n");
    for (i = 0; i < num_imported; i++) {
        emit_prototype(&b, i, 0);
        buf_puts(&b, ";\n");
    }
    bprintf(&b, "\n/* Module functions (%s-1.c ...). */\n", base_name(prefix));
    for (i = num_imported; i < num_funcs; i++) {
        emit_prototype(&b, i, 0);
        buf_puts(&b, ";\n");
    }
    buf_puts(&b, "\n#endif\n");
    write_file(prefix, ".h", &b);
    buf_free(&b);
}

static void write_table(Buf *b) {
    uint32_t i, j, size = table_min ? table_min : 1, *entries;
    if (!have_table) {
        buf_puts(b,
                 "w2c_funcref w2c_indirect(uint32_t index, uint32_t type) {\n"
                 "    (void)index;\n"
                 "    (void)type;\n"
                 "    w2c_trap(\"no table\");\n"
                 "}\n");
        return;
    }
    entries = xcalloc(size, sizeof(uint32_t));
    for (i = 0; i < num_elems; i++)
        for (j = 0; j < elems[i].count; j++) entries[elems[i].offset + j] = elems[i].funcs[j] + 1;
    buf_puts(b, "/* The indirect-call table: function and canonical type index. */\n");
    bprintf(b, "static const struct {\n    w2c_funcref fn;\n    uint32_t type;\n} w2c_table[%" PRIu32 "] = {\n", size);
    for (i = 0; i < size; i++) {
        if (i < table_min && entries[i]) {
            char cname[160];
            func_c_name(entries[i] - 1, cname, sizeof(cname));
            bprintf(b, "    {(w2c_funcref)%s, %" PRIu32 "},\n", cname, types[funcs[entries[i] - 1].type].canon);
        } else {
            buf_puts(b, "    {0, 0},\n");
        }
    }
    buf_puts(b, "};\n\n");
    bprintf(b,
            "w2c_funcref w2c_indirect(uint32_t index, uint32_t type) {\n"
            "    if (index >= %" PRIu32 "u || !w2c_table[index].fn) w2c_trap(\"indirect call to null or out-of-range table entry\");\n"
            "    if (w2c_table[index].type != type) w2c_trap(\"indirect call signature mismatch\");\n"
            "    return w2c_table[index].fn;\n"
            "}\n",
            table_min);
    free(entries);
}

void write_module_unit(const char *prefix) {
    Buf b = {0};
    uint32_t i, j;
    banner(&b, "The translated SultanC seed: memory, globals, table, data and entry.");
    bprintf(&b, "#include \"%s.h\"\n\n", base_name(prefix));
    bprintf(&b, "const uint32_t w2c_memory_max_pages = %" PRIu32 "u;\n\n", memory_has_max ? memory_max : 65536u);
    if (num_globals) {
        buf_puts(&b, "/* Globals; a float is set from its bits by w2c_run. */\n");
        for (i = 0; i < num_globals; i++) {
            switch (globals[i].type) {
                case T_I32: bprintf(&b, "uint32_t w2c_g%" PRIu32 " = 0x%" PRIx32 "u;\n", i, (uint32_t)globals[i].init_bits); break;
                case T_I64: bprintf(&b, "uint64_t w2c_g%" PRIu32 " = UINT64_C(0x%" PRIx64 ");\n", i, globals[i].init_bits); break;
                case T_F32: bprintf(&b, "float w2c_g%" PRIu32 ";\n", i); break;
                case T_F64: bprintf(&b, "double w2c_g%" PRIu32 ";\n", i); break;
            }
        }
        buf_puts(&b, "\n");
    }
    write_table(&b);

    for (i = 0; i < num_datas; i++) {
        bprintf(&b, "\n/* Data segment %" PRIu32 ": %" PRIu32 " bytes at 0x%" PRIx32 ". */\n", i, datas[i].size,
                datas[i].offset);
        bprintf(&b, "static const unsigned char w2c_data%" PRIu32 "[%" PRIu32 "] = {", i, datas[i].size ? datas[i].size : 1);
        for (j = 0; j < datas[i].size; j++) {
            if (j % 20 == 0) buf_puts(&b, "\n   ");
            bprintf(&b, " %u,", in_bytes[datas[i].pos + j]);
        }
        if (!datas[i].size) buf_puts(&b, "0");
        buf_puts(&b, "\n};\n");
    }

    buf_puts(&b, "\nvoid w2c_run(void) {\n");
    if (have_memory) bprintf(&b, "    w2c_init_memory(%" PRIu32 "u);\n", memory_min);
    for (i = 0; i < num_globals; i++) {
        if (globals[i].type == T_F32)
            bprintf(&b, "    w2c_g%" PRIu32 " = w2c_f32_from_bits(0x%08" PRIx32 "u);\n", i, (uint32_t)globals[i].init_bits);
        else if (globals[i].type == T_F64)
            bprintf(&b, "    w2c_g%" PRIu32 " = w2c_f64_from_bits(UINT64_C(0x%016" PRIx64 "));\n", i, globals[i].init_bits);
    }
    for (i = 0; i < num_datas; i++)
        if (datas[i].size)
            bprintf(&b, "    memcpy(w2c_memory + 0x%" PRIx32 "u, w2c_data%" PRIu32 ", sizeof(w2c_data%" PRIu32 "));\n",
                    datas[i].offset, i, i);
    if (have_start) {
        char cname[160];
        func_c_name(start_func, cname, sizeof(cname));
        bprintf(&b, "    %s();\n", cname);
    }
    {
        char cname[160];
        func_c_name(entry_func, cname, sizeof(cname));
        bprintf(&b, "    %s();\n", cname);
    }
    buf_puts(&b, "}\n");
    write_file(prefix, "-module.c", &b);
    buf_free(&b);
}

void write_function_units(const char *prefix, unsigned units) {
    /* Contiguous function ranges balanced by body size: deterministic. */
    uint64_t total = 0, done = 0;
    uint32_t i = num_imported, first;
    unsigned u;
    for (u = num_imported; u < num_funcs; u++) total += funcs[u].body_end - funcs[u].body_start;
    for (u = 0; u < units; u++) {
        Buf b = {0}, code = {0};
        char suffix[32], what[160];
        uint64_t limit = total * (u + 1) / units;
        first = i;
        while (i < num_funcs && (done < limit || u == units - 1)) {
            done += funcs[i].body_end - funcs[i].body_start;
            if (code.n) buf_puts(&code, "\n");
            translate_function(&code, i);
            i++;
        }
        if (i > first)
            snprintf(what, sizeof(what), "The translated SultanC seed, unit %u of %u: functions %" PRIu32 " to %" PRIu32 ".",
                     u + 1, units, first, i - 1);
        else
            snprintf(what, sizeof(what), "The translated SultanC seed, unit %u of %u: no functions.", u + 1, units);
        banner(&b, what);
        bprintf(&b, "#include \"%s.h\"\n\n", base_name(prefix));
        buf_put(&b, code.s ? code.s : "", code.n);
        snprintf(suffix, sizeof(suffix), "-%u.c", u + 1);
        write_file(prefix, suffix, &b);
        buf_free(&code);
        buf_free(&b);
    }
    if (i != num_funcs) die("internal: not every function was written");
}
